/* entity ↔ مفتاح db */
const ENT2KEY = {
  client: 'clients',
  lead: 'leads',
  inter: 'inter',
  audit: 'audit',
  task: 'tasks'
};
const KEY2ENT = {
  clients: 'client',
  leads: 'lead',
  inter: 'inter',
  audit: 'audit',
  tasks: 'task'
};

/* تجميع صفوف السحابة (records + profiles) في كائن db متوافق مع باقي الشاشات */
function cloudRowsToDb(rows, profiles) {
  const out = {
    clients: [],
    leads: [],
    inter: [],
    audit: [],
    tasks: [],
    users: [],
    lookups: JSON.parse(JSON.stringify(DEFAULT_LOOKUPS)),
    projSeq: 0,
    ui: {},
    v: 4
  };
  (rows || []).forEach(r => {
    if (r.entity === 'settings') {
      if (r.data && r.data.lookups) out.lookups = r.data.lookups;
      if (r.data && r.data.projSeq != null) out.projSeq = r.data.projSeq;
      // Tasks are migrated to independent rows by the CRM safety migration.
      return;
    }
    const k = ENT2KEY[r.entity];
    if (k && r.data) out[k].push(r.data);
  });
  out.users = (profiles || []).map(p => ({
    id: p.id,
    name: p.name,
    email: p.email || '',
    authId: p.auth_user_id || '',
    role: p.role || 'engineer',
    perms: p.perms || {
      ...BASE_PERMS
    },
    active: p.active !== false
  }));
  return migrate(out);
}
async function crmApplyBatch(sb, changes, operation, insertOnly = false, expectedActor = null) {
  if (expectedActor) {
    const identity = await sb.auth.getUser();
    if (identity.error || identity.data?.user?.id !== expectedActor) throw Error('تغير حساب الاتصال؛ احتفظ بتعديلاتك وادخل بالحساب الأصلي');
  }
  const {
    data,
    error
  } = await sb.rpc('nitaq_crm_apply_v2', {
    p_operation: operation,
    p_changes: changes.map(({
      entity,
      id,
      before,
      after
    }) => ({
      entity,
      id,
      before,
      after
    })),
    p_insert_only: insertOnly
  });
  if (error) {
    const failure = Error(error.code === 'PGRST202' ? 'قاعدة CRM تحتاج تحديث الحفظ الآمن قبل التعديل' : error.message || 'تعذر الحفظ المشترك');
    failure.definitive = /^(22|23)/.test(error.code || '') || ['40001', '42501', 'P0001'].includes(error.code);
    throw failure;
  }
  if (!data || !['saved', 'already_saved'].includes(data.result)) throw Error('لم يتأكد الحفظ؛ أعد المحاولة بنفس الطلب');
  return data;
}

/* دعوة موظف بإيميله — يترشّح ليتربط تلقائياً بأول تسجيل دخول بنفس الإيميل */
