/* ديف بسيط بين مصفوفتين بالـid — للاستخدام في المزامنة الجزئية والدفع الأولي */
function diffArrById(oldArr, newArr) {
  const oldMap = new Map((oldArr || []).map(x => [x.id, x]));
  const newMap = new Map((newArr || []).map(x => [x.id, x]));
  const changed = [],
    removed = [];
  newMap.forEach((v, id) => {
    if (oldMap.get(id) !== v) changed.push(v);
  });
  oldMap.forEach((v, id) => {
    if (!newMap.has(id)) removed.push(id);
  });
  return {
    changed,
    removed
  };
}

/* رفع كل البيانات المحلية للسحابة دفعة واحدة — أول مرة بعد الربط */
async function pushAllToCloud(sb, db, onProgress) {
  try {
    const rows = [];
    for (const [key, entity] of [['clients', 'client'], ['leads', 'lead'], ['inter', 'inter']]) for (const row of db[key] || []) rows.push({
      entity,
      id: row.id,
      before: null,
      after: row
    });
    for (let i = 0; i < rows.length; i += 100) {
      await crmApplyBatch(sb, rows.slice(i, i + 100), crypto.randomUUID(), true);
      onProgress?.(Math.min(i + 100, rows.length), rows.length);
    }
    return {
      ok: true,
      count: rows.length
    };
  } catch (error) {
    return {
      ok: false,
      error
    };
  }
}

/* بيضيف أي مستخدم قديم مش موجود أصلاً في nitaq_crm_profiles — ومبيلمسش
   أي بروفايل موجود بالفعل (خصوصاً لو مربوط بحساب دخول حقيقي) */
/* دمج بروفايل قديم (من غير حساب دخول) بحساب دخول حقيقي بالفعل —
   البروفايل القديم بياخد auth_user_id بتاع الحساب الحقيقي، والبروفايل
   المكرر الجديد (اللي اتعمل تلقائياً وقت التسجيل) بيتشال. */
async function mergeLegacyProfile(sb, legacyId, realProfile) {
  const {
    error
  } = await sb.rpc('nitaq_crm_merge_profile_v2', {
    p_legacy: legacyId,
    p_real: realProfile.id
  });
  return {
    ok: !error,
    error
  };
}

